<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$adminPage='returns';$adminTitle='مرجوعی و بازپرداخت';$status=scalar_string($_GET['status']??'');$q=text_substr(trim(scalar_string($_GET['q']??'')),0,100);$where=[];$params=[];if(isset(return_status_options()[$status])){$where[]='r.status=?';$params[]=$status;}else$status='';if($q!==''){$where[]='(r.return_number LIKE ? OR o.order_number LIKE ? OR o.phone LIKE ? OR o.customer_name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';$stmt=db()->prepare('SELECT r.*,o.order_number,o.customer_name,o.phone FROM return_requests r JOIN orders o ON o.id=r.order_id'.$whereSql.' ORDER BY r.id DESC LIMIT 300');$stmt->execute($params);$rows=$stmt->fetchAll();require __DIR__.'/partials/header.php';?>
<div class="admin-title"><div><h1>مرجوعی و بازپرداخت</h1><p class="muted">بررسی کالا، بازگشت موجودی و ثبت مرجع استرداد</p></div><a class="btn btn-secondary" href="<?=e(app_url('admin/return-settings.php'))?>">تنظیمات مرجوعی</a></div><form class="filters-admin"><input name="q" value="<?=e($q)?>" placeholder="شماره مرجوعی، سفارش، نام یا موبایل"><select name="status"><option value="">همه وضعیت‌ها</option><?php foreach(return_status_options() as $key=>$label):?><option value="<?=$key?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><button class="btn btn-secondary">فیلتر</button></form><div class="table-wrap"><table><thead><tr><th>شماره مرجوعی</th><th>سفارش</th><th>مشتری</th><th>مبلغ</th><th>وضعیت</th><th>تاریخ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="<?=e(app_url('admin/return.php?id='.(int)$r['id']))?>"><strong><?=e($r['return_number'])?></strong></a></td><td><?=e($r['order_number'])?></td><td><?=e($r['customer_name'])?><br><small><?=e($r['phone'])?></small></td><td><?=fa_number(format_price($r['approved_amount']?:$r['requested_amount']))?></td><td><span class="badge"><?=e(return_status_label($r['status']))?></span></td><td><?=e(jalali_format($r['created_at']))?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6">درخواستی پیدا نشد.</td></tr><?php endif?></tbody></table></div><?php require __DIR__.'/partials/footer.php';
